SELECT COUNT(*) 
FROM cards 
WHERE border_color = 'white' AND power IS NOT NULL AND CAST(power AS INTEGER) < 3;

SELECT COUNT(*) AS italian_rules_text_count
FROM cards
WHERE set_code = 'csp' AND (language = 'it' OR printed_language = 'it') AND printed_text IS NOT NULL;

SELECT ROUND(AVG(weight), 1) AS avg_weight_left_footed_players
FROM Player
WHERE preferred_foot = 'left';

SELECT ROUND(AVG(weight_kg), 2) AS avg_female_hero_weight_kg
FROM superhero
WHERE gender = 'Female' AND weight_kg IS NOT NULL;

SELECT COUNT(*) AS neutral_heroes_with_full_name
FROM superhero
WHERE alignment = 'neutral' AND full_name IS NOT NULL AND TRIM(full_name) != '';
